INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p389994-ise398', 'stk-jotun', 'ISE 398', 'info', '{"desc": "http://img23.imageshack.us/img23/2664/coopl.jpg\n\nJotun is looking for Co-op Trainees in the following Majors:\n\n**\\(1\\) Industrial engineer in Yanbu.****\\(1\\) Chemical engineer in Jeddah or Yanbu.****\\(1\\) Mechanical engineer in Yanbu.****\\(1\\) Accountant in Jeddah.****\\(1\\) HR position in Jeddah \\(Industrial Engineer, Marketing or Management\\).** We offer:\n\n- A professional working environment that focuses on continuous improvement and innovation.\n\n- An international corporate culture founded on our four values; Loyalty, Care, Respect and Boldness.\n\n- Contract for each student with a monthly salary of SR 3000 (Basic Salary: 2400, Housing Allowance: 500 and Transportation Allowance: 100).\n\n- Prepared Co-op plan for each position.\n\n- Working hours 7:30 AM to 5:00 PM from Saturday to Wednesday.\n\n- Trainees will perform On-Job projects during the Co-op Period.\n\n- One week vacation will be given during the Co-op\n\nIn addition, competent trainees will have an opportunity to Join our family after graduation.\n\nC.V.s will be received & Exams will be held during the Career Day Event on 12-16 April.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/co-op-opportunities-in-jotun/72286/1", "user": "JOTUN", "ts": 1239280300000, "tid": 72286, "pn": 1}}', 1239280300000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1402818-ise398', 'stk-user2352', 'ISE 398', 'info', '{"desc": "لطلاب هندسة النظم الصناعية ، كل ما تحتاجه لتسجيل الـcoop وأفضل الشركات\n\nالسلام عليكم\nحياكم الله أخواني طلاب الهندسة الصناعية ،،\nيسرني في هذا الموضوع أن أكتب لكم جميع الخطوات والمعلومات المهمة قبل وبعد تسجيل التدريب التعاوني\nISE350+351 COOP صيف +ترم أول\nISE351+352 COOP ترم ثاني + صيفي\n\nوطالب الكوأب يطبق فترة سبعة أشهر صيفي مع ترم كامل في شركة يكسب من خلالها خبرة عملية ،،\n\nطبعا تختلف الفائدة من شركة لأخرى حسب الشركة فمثلا في سابك وأرامكو تعتبر أقل فائدة من جنرال ألكترك ويونيلفر ،،\nوينصح بالتطبيق بشكل عام في شركة انتاج صناعية مثل شركة يونيليفر أو بروكتر& قامبل P&Gأو جنرال إليكتريك ge أو pwc أو الشركات الجديدة مثل شركة صناعة الورق NAPCO ،،\n\nوفي نهاية الكوأب فيه قريد لـ9 ساعات عوضا عن ثلاث مواد ، تقدر ترفع بها معدلك إذا ابدعت في الشركة بعمل بروجكتات محترمة وكيس ستدي وكتبت ريبورت كامل وسويت برزنتيشن ناجح ،،\nالكورسات المفيدة والمطلوبة من كلام خريجي التخصص قبل الكوأب\n422+ISE303+320+323+325+307+391+390+402+405\nوME322\\323\nوأنصح دائما بأخذ الكورس Mgt-210 قبل الكوأب كمادة اختيارية على طول بعد ما تخلص الكورس Engl-214 لأنه مفيد في تطوير مهارات الإتصال في مجال الأعمال في الشركات\nويستحسن أيضا تدرس كورس اختياري من التخصص قبل الـcoop مثل 470 أو 420 تفيد في بروجيكتات الشركات ، وأيضا يستحسن إنهاء فوق 105 ساعة قبل تسجيل الـcoop حتى يتبقى ساعات قليلة في آخر سمستر\n\nودائما ينصح بالكوأب لمن لا يهمه التأخر سمستر زيادة ويبحث عن اثبات وجوده في شركة معينة يطمح بالالتحاق بها فيما بعد ، وهكذا\n\nالخطوات بالتفصيل :_\n1- تروح الكورديناتور حق الكوأب وتاخد الابلكيشن منو وتوقعو من الادفايزر اللي انتاا راح تختاره … طبعا عشان تلحق من الافضل انك تختار الادفايزر من الاسبوع الأول أو الثاني أو قبلو من الترم يعني لو فكرت الان احتمال كبير ما تحصل الادفايزر اللي انتاا تبغاه …\n\n2- تروح للادفايزر توقع الورقة منو مثل د. هارون بيرم أو نبيل نحاس أو أي دكتور آخر تعرفه …\n\n3- تسلم الورقة للكورديناتور د.سمير العامر حاليا وتأخذ منه خطاب الترشح للكوأب بعد توقيعه وختمه من التشيرمان في القسم …\n\n4- تأخذ نسخة خطاب تعريف وترشيح من ادارة التدريب مع نموذج فرصة تدريب تعاوني COOP\nاختيار الشركة … فيه طريقتين … يا إنك تجيب موافقة الشركة بنفسك عن طريق يوم المهنة أو أي طريقة أخرى … أو إنه تكون عن طريق مكتب التدريب التعاوني في مبني 68 حاليا ادارة التدريب … ولا تنسى اعداد سيرتك الذاتية CV التي بموجبها مع ورقة الترشيح راح تحصل فرصة تدريبية.\nعبر هذا الموقع تقدر تشوف الفرص المعروضة من ادارة التدريب\nhttp://www2.kfupm.edu.sa/stutraining/\n\n5- بعد ما تتأكد إنه الشركة أرسلت أوراقك للجامعة إنه تاخد الكوأب عندهم … بعد الفاينلات تمرهم في مبني 68 الدور التاني مكتب 108 عند تركي الدوسري حالياً وتاخد ظرف مغلق يحتوي على خطاب التوجيه عشان تسلمه الشركة اول ما تداوم وتكمل تعبئة باقي الأوراق والنماذج مثل دليل الإتصال …\n\n6- خلال فترة الكوأب احرص إنو تكون متواصل مع الادفايزر حقك , وبعضهم يطلب يشوفك … فممكن تطلب من الشركة اجازة عشان تجي الجامعة … وطبعا لاتنسى الاشياء المطلوبة منك واللي راح يشروحها لكم في محاضرة عن الكوأب قبل ما تطلعو مثلا زي (التقييم ، الخطة، الخ …) وكمان مطلوب منك ثلاثة progress reports خلال فترة الكوأب السبعة أشهر\n\n7- بعد ما تخلص من الكوأب (طبعا حاول إنك ما ترجع الجامعة إلا وإنت مخلص الريبورت عشان تسلمه للادفايزر على طول لانه غالبا حيمرمطك عدل وبدل …\n\n8- بعد ما يعطيك الادفايزر الموافقة على الريبورت ok… تروح تختار الكوميتي دكتورين والادفايزر حقك عشان تسوي البرزتيشن … وتحجز لك كلاس عبر موقع المسجل\nأو تدور لك كلاس أو لاب فاضي في مبنى 22\nوتاخذ لك 3 نسخ من coop Exam Evaluation من سكرتير القسم\n\n9- اول ما ترجع حاول انك تتأكد انه التقييم وصل لتركي الدوسري ( طيب الذكر) … لانه غالبا يسوي فيها ساندويشات ويضيعها ويطلب منك انو يرسلوها اكتر من مرة . 😆\n\n10- لا تنسى تنسق مع الكورديناتور لانه لازم تسلم له نسخة من الكوأب ريبورت … شوف كيف يبغاه … غالبا نسخة PDF في CD مع نسخة مطبوعة ومغلفة\n\n11- بعدها خلاص … كل سنة وانتا طيب …\n\nملاحظة : جميع أوراق COOP تحصلها مطبوعة ومجهزة على طاولة على يسارك أول ما تخش مكتب قسم هندسة النظم ،،\n\nفي المرفقات راح تجد عناوين أغلب الشركات اللي ممكن تحصل فيها فرصة COOP\nISE 351,352 COOP\nبالتوفيق للجميع 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/165847/1", "user": "user2352", "ts": 1411518540000, "tid": 165847, "pn": 1}}', 1411518540000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p356283-ise398', 'stk-user5089', 'ISE 398', 'info', '{"desc": "اخواني انا عندي Coop Training و ان شاء الله ابغى اخذه في شركة عالمية تهتم في التدريب وبالذات في الهندسة الصناعية\n\nاذا ما عليكم امر كل ابغى احد ينصحني بشركة خارج المملكة تهتم في التدريب عشان اراسلهم\n\nوالله يكتب الي فية الخير\n\nواشكر لكم حسن التعاون\n\nنسيت اقول لكم اخوكم من جامعة الملك عبدالعزيز:p\nKFUPM سابقا ( اوريااااااااااااااا) 🤣", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-training/69817/1", "user": "user5089", "ts": 1232994545000, "tid": 69817, "pn": 1}}', 1232994545000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p343987-ise398', 'stk-user2068', 'ISE 398', 'info', '{"desc": "هذي المعلومات اللي عندي وإن شاء الله تستفيد منها :\n\nA student may take the co-op training program if he satisfies the following\nHis GPA is above 2 in both the cumulative and major\nThe student finished at least 85 credit hours\nHe finished English 214 and the four out of the following five courses\n\nISE >>>> SE-303 ,SE-320 ,SE-323 ,SE-402, SE-405\n\nCISE>>>> CISE-311, CISE-312, CISE-315, CISE-401, CISE-418\n\nThe student takes the co\\-op work term before last term for his graduation.بالنسبة للفرق بين الكووب والتريننق هو مادتين بس السنيور بروجكت و 305ومادة اختياريه حرة\n\nوبخصوص الشركات ماعندي معلومة عنهم , وبالتوووفيق إن شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/co-op-ise/68869/3", "user": "user2068", "ts": 1230309377000, "tid": 68869, "pn": 3}}', 1230309377000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p529904-ise398', 'stk-guest', 'ISE 398', 'info', '{"desc": "هادا الإيميل اللي وصلني على إيميل الجامعة من شركة GE\n\nInternship &Coop:\nAn internship or co-op at GE gives a student hands-on experience,\nworking on challenging projects with some of the best minds in business. This is a superb opportunity to give his career a head start while making valuable Contacts. The Coop work experience is a vitally important tool for helping a student determines the course of his career, giving him valuable insight into the workplace, useful experience, and helpful contacts for the future.\n\nIf your Major is: Electric Engineering, Mechanical Engineering, Industrial Engineering, or Finance, Send your email to:\n\nthamer.al\\-fakeeh@ge.com\n\nGE invests over $1 billion in training & development. You’ll never stop learning and growing, because GE is a culture committed to education. We’re NOT training Employees; we’re DEVELOPING talent", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-me-ise-ge/82698/1", "user": "Guest", "ts": 1264591889000, "tid": 82698, "pn": 1}}', 1264591889000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p955201-ise398', 'stk-kfupm_boy', 'ISE 398', 'info', '{"desc": "السلام عليكم يا أخوان…\n\nعندي مقابلة مع شركة المهيدب للأغذية يوم السبت …اللي كلمني قال أنها على الطريق الساحلي\nلكني طلعت دورتها لين عييت و ما عرفت مكانها!\nإذا في أحد يعرف مكانها…و يقدر يوصف لي من عند اشارة الكوبري اللي جنب وكالة المرسيدس أكون له شاكر!!\n\nأنا تخصصي هندسة صناعية و زهقت من البطالة و أدري الشركة من اسمها صغيرة و ما تحمس بس ما باليد حيلة و إذا تعرفون شركات توظف تخصصي لا تبخلون على أخوكم!\n\nأنا معدلي 2.75", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/117157/1", "user": "KFUPM_BOY", "ts": 1325148244000, "tid": 117157, "pn": 1}}', 1325148244000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1127778-ise398', 'stk-moho990', 'ISE 398', 'info', '{"desc": "شكرا اخوي goooood و بغيت اسأل وش رايكم بشركات الكونسلتنج لتخصص الهندسة الصناعية مثل (شركة برايس وترهاوس كوبرز PwC ، و ديلويت اند توش بكر أبو الخير )\n\n١- هل تنصحون فيها ؟\n٢- هل فيها بروجكتات كويسة اقدر اسوي فيها ريبورت وبرزنتيشن محترم ؟\n٣-و كيفها من ناحية طول الدوام\n٤- وايهم افضل اطبق كواب بشركة عادية ولا بكونسلتنج", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/133775/7", "user": "moho990", "ts": 1354376026000, "tid": 133775, "pn": 7}}', 1354376026000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1445226-ise398', 'stk-user8581', 'ISE 398', 'info', '{"desc": "من ايميل الجامعة :\n\nفرص التدريب الخارجي لدى الشركة السعودية للكهرباء\n\nعزيزي الطالب …السلام عليكم ورحمة الله وبركاته …في إطار التعاون بينها وبين الجامعة، تقدم الشركة السعودية للكهرباء فرص تدريب تعاوني في فرنسا، للطلاب المرشحين للتدريب التعاوني في تخصصات: الهندسة الكهربائية، الهندسة الميكانيكة، الهندسة المدنية، الهندسة الصناعية والنظم…في حال رغبتكم في التقديم على هذه الفرص، نأمل تسجيل البيانات المطلوبة في الرابط التالي:\nرابط التسجيل\n\nعلمًا بأن آخر موعد للتسجيل هو الساعة السابعة صباح يوم الأحد 25جمادى الآخرة 1437 هـ، الموافق 3 أبريل 2016 م.\nمع تمنياتنا للجميع بالتوفيق …إدارة التدريب\n\nلاتضيعون هذي الفرصة ياشباب + سجلوا في الرابط من الحين عشان ماتصير نفس سالفة يوم التدريب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/161-152-153/170272/146", "user": "user8581", "ts": 1459254432000, "tid": 170272, "pn": 146}}', 1459254432000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p172520-ise398', 'stk-user3', 'ISE 398', 'info', '{"desc": "ذهبت مُسرعاً لكي ألتقي به, فوجدته ينتظرني بكل تواضع و هدوء. لقد توقعت أن رجلاً في منصبه سيسألني عن طريقة لباسي او لماذا لم أحلق ذقني… او شيء من هذا القبيل… لكن شيئاً من هذا لم يحدث, فلقد استقبلني و أجلسني بجانبه و كأنني أعرفه منذ مدة ليست بالقصيرة… كنت أتتوقع أن أجواء من السكون و السكوت ستخيّم علينا, إلا أنه بادرني بأمطار من الأسئلة عن المنتدى و عن نشأته… أخذ يسألني عن كل صغيرة و كبيرة مما أثار حماسي المُطلق. أخذت أسرد له قصة هذه السفينة, و لقد تعجبتُ حينما أخبرني بأنه قد زار المنتدى في السابق (منذ سنتين تقريباً) بهدف التعاون مع المنتدى لحجز (بانر) دعائي للشركة التي كان يعمل فيها وقتئذٍ …Unilever.\n\nثم بادرني بالأسئلة الشخصية… و مع تبادلنا لبعض المعلومات إكتشفتُ أن هذا الرجل حريص على التوظيف و محاربة البطالة… فتجده يتنقل من منتدى لآخر يعرض فيه وظائف في الجهة التي يعمل بها, وهذا على حد علمي, عملٌ لا يقوم به إلا رئيس متواضع للناس ولا يتغير بتغيّر منصبه…\n\nhttp://j.loading.googlepages.com/KFUPMcareerday.JPG\n\nنرحب جميعاً بالأستاذ /طارق الكاهلي - رئيس قسم التوظيف في بنك ساب. و يطيب لنا أن نعرض لكم الأسئلة التي عُرضت عليه و تفضّل بإجابتها…\n\n1) عرفنا بنفسك… إسمك… سنة التحاقك بالجامعة… التخصص… سنة التخرج…الخبرة الوظيفية\n\nطارق حسين الكاهلي، دفعة 97. تخرجت من الجامعة في عام 2002 من قسم هندسة نظم. عملت في الوظائف التالية:\n\n2001 تدريب تعاوني - شركة يونيليفر\n2002 مدير تحت التدريب – يونيليفر\n2004 مدير التوظيف – يونيليفر\n2005 مدير توظيف الخريجين - الشرق الأوسط - يونيليفر\n2006 و حتى تاريخه، رئيس إدارة التوظيف – بنك ســـاب\n\n2) نبذة عن موقعك الوظيفي في البنك, و عن الأعمال التي تقوم بها في هذا القسم؟\n\nأقوم بقيادة فريق عمل يعنى بالآتي:\n\n- تسويق البنك عبر مختلف الجامعات و المعاهد و القنوات المناسبة لإستقطاب الكفاءات الشابة للبنك\n- إدارة مركز قياس و تقويم لتقييم قدرات المتقدمين و أيضا لتقييم موظفي البنك لأسباب تطويرية\n- استقطاب متقدمين ذوو خبرات\n- استكمال الإجراءات الإدارية للمنضمين الجدد للبنك لجعل انضمامهم للبنك يتم بكل يسر و سهولة\n- تطوير قدرات البنك في التوظيف من حيث تطوير الكفاءات الشابة في الإدارة، وتطوير الإجراءات و أنظمة المعلومات التي تساند الفريق في أداء عمله.\n\nhttp://j.loading.googlepages.com/1-t.JPG\n\n3) حدثنا عن مرحلتك التعليمية من الابتدائية و حتى المرحلة الثانوية؟\n\nابتسمت عند هذا السؤال… الحقيقة رحلة الدراسة كانت غريبة نوع ما. فقد درست أغلب الإبتدائية في مدارس الأندلس لكن انقطعت لسنة و نصف لمرافقة والدتي {أطال الله في عمرها} في بريطانيا حيث كانت تدرس. ثم عدت للمملكة و أكملت دراستي حتى الأول ثانوي، عندها درست منهج الثانوية البريطانية في نفس عام الأول ثانوي. و كنت أدرس بالنهار في مدارس الثغر و بالليل أدرس منهج الثانوية البريطانية، والتي أهلتني لدخول الجامعه فور انتهائي من تلك السنة.\n\n4) لماذا إخترت جامعة الملك فهد؟ و هل لالتحاقك بالجامعة قصة؟\n\nأخي كان التحق بها قبلي و كان يشيد بالجامعه كثيرا. لم يكن هناك قصة أذكرها، لكني لا أنسى من ذلك دموع والدي عندما اتصلت الجامعة لإخباري بالقبول.\n\n5) السنة التحضيرية “الأوريا” لها ذكرياتها في ذهن كل طالب جامعي… فما هي ذكريات الأستاذ طارق الكاهلي مع عالم الأوريا (بقليل من التفاصيل)؟\n\nأخبروني أن علي ان أراجع مبنى 17 لأخذ البطاقة و انهاء بعض الإجراءات. كانت نقطة الإنطلاق لاين 647 حيث سكنت في أول اسبوع مع أخي. بالطبع دخلت أول مبنى صادفني، باحثا عن رقم المبنى من الداخل حيث لم أجد أرقام على واجهة المبنى، هذا كان في سبيل أن أستدل من رقم المبنى على مبنى 17. بعد ان دخلت المبنى وجدته مظلما من الداخل و به سراديب مظلمة و خرج لي شخص بسروال سنة من غرفته ليخبرني بمتعة، انني كنت في العماير البنية و ليس الجبل.\n\nhttp://j.loading.googlepages.com/2-t.JPG\n\n6) موقف لازلت تذكره في السنة التحضيرية؟\n\nأخبرني في أول أسبوع لي بالجامعة، عميد الأوريا آنذاك د.فهد السعيـد، انني سأفصل من الجامعة إن رسبت في الـ Math لأنها كانت مع الرياضة و الـ shop المواد الوحيدة في جدولي. اجتهدت خوفا من الفصل و حصلت على مرتبة شرف أولى.\n\n7) ما سبب إختيارك لتخصصك؟ و هل كنت تواجه صعوبات في إتخاذ القرار؟\n\nأعجبني قدرة مهندسي النظم في زيادة الإنتاجية عن طريق حسابات هندسية وإدارية و هذا الذي جذبني.لم تكن كل القرارات سهلة طبعا، هناك قرارات صعبة اتخذتها.\n\n8)هل لك تجارب في عالم النشاط الطلابي؟ و ما مدى تأثيرها الإيجابي عليك كطالب في الجامعة؟\n\nنعم كنت عضو في نادي العلاقات العامة. كان لها فضل كبير بعد الله في تطوير قدراتي الشخصية، بالإضافة لتكوين مجموعة متميزة من الأصدقاء، أعتز بهم إلى هذا اليوم.\n\n9) أسماء دكاترة و أساتذة تدين لهم الكثير, لا زالت عالقة في ذهنك؟\n\nد. فؤاد السني، د.عبدالباسط أنديجاني، و د.عمر التركي. كما أدين كثيرا لأساتذتي في الحياة الذان علماني خير دروس ما زالت ترشدني إلى اليوم، والدي حسين الكاهلي ووالدتي د. أسماء باهرمز، أسأل الله أن يحفظهما و يطيل في أعمارهم.\n\n10) ما هي أبرز هوايات طارق الكاهلي؟\n\nالسفر، القراءة، العلاقات الإجتماعية و ركوب الخيل متى ما أمكن.\n\n11) هل تفكر في إكمال دراستك العليا قريباً؟\n\nلا.\n\n12) هل تنصح الخريج أن يتوظف أولاً… أم يكمل برنامج الماجستير؟\n\nالجامعات المرموقة التي تقدم برامج MBA أغلبها تطلب خبرة سابقة قبل الإلتحاق ببرنامج ماجستير، وأنا أتفق معها في الرأي.\n\n13) لماذا يركز القطاع البنكي في توظيف الخريجين تحت برنامج (Corporate Finance), مالمميز في هذا المجال الذي يجعل أغلب البنوك توظف فيه؟\n\nيكون لدى خريجين ال Finance خلفية جيدة في عمليات البنك المختلفة والأسس التي تعمل بها. لكن يجب التنويه أن الإدارة البنكية ليست علم نووي و يمكن لخريج أي تخصص أن يتقنه.\n\n14) ما هو موقفكم من سياسة “الحشو التوظيفي”… مثلاً أن يأتي خريج في الهندسة الصناعية و يتم توظيفه في قسم الإدارة المالية؟\n\nالرئيس التنفيذي لأحد البنوك العالمية في المملكة خريج كلية جوية، وهناك أمثلة كثيرة. كما قلت سابقا، ليس هناك علم نووي في الموضوع، و من لديه رغبة في مجال، سيتعلمه.\n\nhttp://j.loading.googlepages.com/3-t.JPG\n\n15) يقال أن الخريج حينما يختار إكمال دراسته العليا, فإنه يواجه صعوبة في الحصول على وظيفة نظراً لانعدام الخبرة التي تتطلبها الجهات التوظيفية… هل هذه المقولة صحيحة؟ و ماهي الطريقة السليمة للتوفيق بين إكمال الدراسة و الحصول على وظيفة؟\n\nللعمر دور، حيث أن الخريج يسهل عليه الإلتحاق بوظائف كثيرة عندما يكون في حدود ال25 عاما فأقل، أما بعد ذلك، فيجب أن يكون لديه خبرة تشفع له، إذا ما أراد الحصول على وظيفة مرموقة. الإنطلاق في الدراسات العليا يجب ان يكون مدروسا ومخططا، ويؤسفني بعض الأمثلة من الشباب الذين –يمطون- في دراساتهم العليا فيأخذ double major ثم ماجستير أو ربما اثنين. كثيرا يكون هذا في سبيل البقاء في الخارج أطول فترة ممكنه، ثم يستيقظون في عمر ال 26 إلى 30 و هم لا يملكون أي خبرة و يبحثون عن فرص.\n\n16) بحكم خبرتك في مجال التوظيف, ما الذي يميز خريج جامعة البترول في نظرك عن أقرانه من خريجي الجامعات الأخرى؟\n\nشهادتي في خريجي جامعة البترول مجروحة، و لكني أظن انه لو لم تكن هناك جامعه أخرى في المملكة غيرها لكفت.\n\n17) ما هي النقاط التي تتمنى لو كانت موجودة بقوة و بكثافة في خريج جامعة البترول, او بمعنى آخر… تتمنى أن تتوفر في خريج البترول؟\n\nربما ينقص الجامعة ما يسمى بـ diversity و هو التنوع الثقافي من حيث جنسيات الطلاب. فلو كان موجودا لطور في الطلاب مهارات التعامل مع الثقافات الأخرى و هذا مطلوب في العالم اليوم و يمكن الحصول عليه عن طريق العمل مع أجانب في شركات معينة.\n\n18) لقد عملت في شركة كبرى قبل التحاقك بـ ساب. أنا أجزم بأنك صادفت مجموعة ليست قليلة في كلا الجهتين, من خريجي الجامعة… هل نستطيع أن نقول بأن خريجي جامعة البترول هم العامل البشري المؤثر و الأساسي في كلا القطاعين؟\n\nنعم، لهم نصيب الأسد من الوظائف القيادية.\n\n19) أين ترى نفسك كخريج من جامعة الفهد, بعد عشرة سنوات؟\n\nأن أكون قادرا على خدمة الجامعه بشكل خاص، وخدمة المجتمع بشكل عام و ذلك حسب اختصاصي عن طريق المساهمة في تطوير أبناء المملكة مما يكون له مردود إيجابي على الإقتصاد، فشبابنا هم النفط الذي لا ينضب بإذن الله.\n\n20) ماذا تنصح إخوانك الطلاب و المقبلين على التخرج قريباً؟\n\nالطريق شيق و ممتع أمامكم، و هناك الكثير مما يمكن أن تضيفوه حيث أنكم النخبه و الجميع ينتظر منكم الكثير أيضا، فالهمة الهمة.\n\n21) هل صحيح أن المعدل هو المقياس الحقيقي للتوظيف بشكل عام؟\n\nلا\n\n22) قمتَ بإلقاء محاضرات تعريفية أكثر من مرة في قاعات الجامعة, مالإنطباع الذي ترسخ لديك من طلاب الجامعة مقارنة بالوقت الذي كنت فيه طالباً مثلهم؟\n\nلا أتذكر جيدا لأنني في وقت دراستي لم أكن أقيم الآخرين. لكنني أفرح كثيرا عندما أقابل نخبة من الطلاب أرى فيهم عوامل النجاح و أنا متأكد أنهم سيكونون في مواقع مرموقة بإذن الله بعد عدد من السنين.\n\n23) ما فائدة اللقاءات مع الطلاب في نظرك؟ و مالنتيجة المرجوة من طرفكم كإدارة توظيف؟\n\nالتسويق لإسم البنك و من ثم اختيارها الطلاب للتوظيف عند تخرجهم.\n\n24) ما هو رأيك في منتدى طلاب جامعة الملك فهد للبترول و المعادن sKFUPM ؟\n\nمنتدى رائع و أتوقع للموقع مستقبل باهر، بالذات إذا تم تفعيله مع الأندية الطلابية و نادي الخريجيين. إلى الآن لا نملك وسيلة فعالة للتواصل بين الخريجين و قد يكون مثل هذا المنتدى وسيلة فعالة.\n\n25) يتميز منتدانا بمتابعة حثيثة من قبل مسؤلي الجامعة و على رأسهم معالي الدكتور خالد السلطان… هل سبق و فكرتم في التواصل مع خريجي الجامعة عن طريق المنتدى؟\n\nنعم لدينا خطط لهذا و لكن لا أستطيع الإفصاح عنها الآن.\n\n26) رسالة تود أن يقرأها أعضاء منتدى sKFUPM ؟\n\nأتمنى أن يكون هذا اللقاء ذو فائدة و أتمنى أن يثمر المنتدى في الحفاظ على التواصل بين أبناء الجامعة خلال دراستهم و بعد تخرجهم.\n\nhttp://j.loading.googlepages.com/4-t.JPG\n\nشكراً جزيلاً للأستاذ طارق الكاهلي على وقته الثمين, وعلى تجاوبه مع المنتدى… وإلى أن نلتقي معكم في لقاء آخر مع شخصية قيادية أخرى تخرجت من هذه الجامعة, لكم مني أجمل و أزكى تحية 🙂\n\nابو سمر … sKFUPM … الرياض\n\n@46@", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/56618/1", "user": "user3", "ts": 1180638342000, "tid": 56618, "pn": 1}}', 1180638342000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1302793-ise398', 'stk-_273', 'ISE 398', 'info', '{"desc": "شركة مثل ماقالوا الشباب من اكبر اربع شركات عالمية في الخدمات المهنية والمحاسبة\nوطبعا للاخ بما ان تخصصه Industrial engineering فبيكون في قسم الاستشارات(Consulting)\nالدوام من 8 الى 6 وحنا كانوا يعطونا راتب 4000 في الكوأب.\nوعن نفسي استفدت من تجربتي معاهم.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pwc/153644/6", "user": "_273", "ts": 1386569769000, "tid": 153644, "pn": 6}}', 1386569769000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1034467-ise398', 'stk-al-hashim', 'ISE 398', 'info', '{"desc": "السلام عليكم ورحمه الله وبركاته\n\nتعلن شركة الكاتيل لوسنت عن فرص للتدريب التعاوني وذلك في مدينة الرياض للتخصصات التالية:\n\nالهندسة الصناعيه والنظم … عدد 2\nالهندسة الكهربائيه (اتصالات) … عدد 12\nنظم المعلومات الادارية … عدد 2\nهندسة الحاسب الآلي … عدد 1\n\nالشركة لها مشاريع كثيره مع مشغلي الخدمات بالمملكة مثل الاتصالات السعوديه وموبايلي وزين وكذلك بعض الشركات العملاقه مثل ارامكو السعودية\n\nللتواصل:\nيرجى ارسال السيرة الذاتيه على البريد التالي\nIbrahim.olayan@alcatel\\-lucent.com\nالسيد ابراهيم العليان - الرياض\nالهاتف: 012839080\n\nعلى ان يكون عنوان الرساله: تدريب تعاوني – جامعة الملك فهد للبترول والمعادن\n\nبالتوفيق يا شباب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-training-with-alcatel-lucent-2012/125322/1", "user": "AL-HASHIM", "ts": 1336484139000, "tid": 125322, "pn": 1}}', 1336484139000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p471588-ise398', 'stk-ise-26', 'ISE 398', 'info', '{"desc": "2- حصول الطالب على معدل تخصص جيد لا يقل عن 2.00وبالذات في الكورسات التالية بعد إنهائها\n\nise(303+320+323+325+402+405) should be ok\n\nالملاحظه الأولى : ما اتوقع يقدرون يجبرون الطلاب لازم يجيبون قريدات جيدة بالمواد هذي\n\nهي مجرد تخلص 4 كورسات من اصل 5 كورسات محدده\n\nالملاحظه الثانيه : مثل ما قال الأخ قصي ise 325 ما اتوقع انها متطلب\n\nوتراني انا ما اشكك بشي … بس مستغرب من نظامهم الجديد\n\nلاني دخلت على موقع كلية الهندسة الصناعيه … ولقيت نسخه قديمة عن المتطلبات\nاتمنى يحدثونها …\n\nوالله يعطيك العافيه يا مهندس\n\nتقبل مروري", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-ise/78543/3", "user": "ISE-26", "ts": 1254947008000, "tid": 78543, "pn": 3}}', 1254947008000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1142915-ise398', 'stk-s-ise', 'ISE 398', 'info', '{"desc": "السلام عليكم\nانا طالب في الهندسة الصناعيةISE وإن شاء الله السمستر الجاي راح اطلع coop\nوحصلت على ثلاث فرص فاتمنى مشورتكم ايها افضل\n1- pwc في الرياض في consulting\n2- هيئة سوق المال في قسم الاستراتيجيات\n3- صندوق التنمية الصناعي في ادارة المشاريع قسم الفني\n\nنتمنى مشورتكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-pwc/136471/1", "user": "s-ISE", "ts": 1355658395000, "tid": 136471, "pn": 1}}', 1355658395000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1433843-ise398', 'stk-hisham.s', 'ISE 398', 'info', '{"desc": "نوع التدريب ( COOP ):\n\nاسم الشركة أو جهة التدريب :\n\nهيئة السوق المالية -CMA -Capital Market Authority\n\nالسنة :\n2015\n\nالتخصص :\nالإدارة - الموارد البشرية\n\nمكان التدريب :\nمدينة الرياض\n\nالمزايا :\n1-مكافئة شهرية مقدارها 3,500 رغŒال لطلاب الجامعات من مدينة الرياض 5,000 رغŒال من خارجها.\n2-مكافئة شهرية مقدارها 1,500 رغŒال لطلاب المعاهد من مدينة الرياض و2,500 رغŒال من خارجها. ً\n3-خلال فترة التدريب ،تمكين الطالب / ــة من دخول إختبار الهيئة CME1 والحصول على الشهادة مجانا\n4- إمكانية حضور الدورات الداخلية المنعقدة داخل الهيئة.\n5- الحصول على شهادة خدمة عن فترة التدريب بالهيئة .\n\nطريقة التقديم :\n\nطن طريق زيارة موقع الهيئة http://www.cma.org.sa/ > التوظيف > برنامج التدريب التعاوني.\nhttp://www.cma.org.sa/Ar/********s/COOPBrochure.pdf\n\nإضافات:\nبيئة العمل احترافية وجميلة جداً\nالخبره المكتسبة كبيرة ، والموظفين يتمتعون بخبره ومهنية عاليه .\n\nالتخصصات المطلوبة : تخصصات كلية الإدارة الصناعية + الهندسة الصناعية + تخصصات وفروع تقنية المعلومات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170460/24", "user": "hisham.s", "ts": 1447937679000, "tid": 170460, "pn": 24}}', 1447937679000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1485950-ise398', 'stk-ali_abdullah', 'ISE 398', 'info', '{"desc": "نوع التدريب ( COOP )\nاسم الشركة أو جهة التدريب : Aramco\nالسنة : 162-163\nالتخصص + الجامعة: KFUPM - ISE\nمكان التدريب + القسم : Ras Tanura\nالمكافأة : 4500 ريال\nطريقة التقديم : عن طريق موقع الشركة ، وتم ترشيحي من الجامعة\n\nإضافات ( مثلا : رأيك في الشركة , الإستفادة, الكورسات الي يمكن تفيدك في التدريب… ) :\n\nالفائدة في القسم الي كنت فيه معدومة ، مافيه استعداد ابدًا لطالب كواب جاي يتدرب عندهم.\nلازم انت تتحرك وتشوف لك شيء يشغلك بالدوام\nلكن انسى الموظفين يعطونك شغل جامد ، اغلب الشغل كان تعديلات على ملفات اكسل وكم حاجة بسيطة.\n\nطبعًا ارامكو شركة كبيرة والفائدة بالتدريب تعتمد على القسم الي بتكون فيه ، بعض الاقسام تهتم بالمتدرب وبعضهم ولا كأنه موجود.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170460/67", "user": "Ali_Abdullah", "ts": 1515666349000, "tid": 170460, "pn": 67}}', 1515666349000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1221492-ise398', 'stk-_2155', 'ISE 398', 'info', '{"desc": "اخي العزيز القسم هذا جدا قوي خصوصا على كلام اخوي drake اذا انت هندسة صناعية والشركه قويه جدا جدا\nانا تخصصي هندسة صناعية سابك دقو على عشان اتوظف عندهم في هذا القسم قسم جميل ويحمل العديد من عمليات التحليل والجدوله\nبالتوفيق ان شاء الله\n\nحبيت اسالك ياغالي كيف قدمت عليهم واذا انت بتروح لهم هل من الممكن ارسل لك السفى حقي على الخاص حقك وتعطيهم على طريقك الله يجزاك خير هذا في حاله رحت شاااكر لك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/supply-chain/144378/3", "user": "_2155", "ts": 1368365228000, "tid": 144378, "pn": 3}}', 1368365228000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1204208-ise398', 'stk-nayef', 'ISE 398', 'info', '{"desc": "تعلن شركة تيناريس عن توفر فرص لبرنامج التدريب التعاوني (COOP) والمقرر بدءه خلال يونيو من العام 2013 لمدة 28 أسبوعاً\n\nحيث تقدم الشركة للمتقدمين السعوديين لهذا البرنامج فرصة الإحتكاك بأصحاب الخبرة في مجالها و التدريب المناسب في بيئة عمل مثالية يكون الإحتكاك فيها بموظفين ومدراء من جنسيات مختلفة حول العالم مما يضمن اكتساب الخبرة بالإضافة الى العوائد المادية المنافسة\n\nالتخصصات المطلوبة:\nالهندسة الميكانيكية\nالهندسة الكهربائية\nالهندسة الصناعية\nالهندسة الكيميائية\n\nالرجاء إرسال السيرة الذاتية إلى البريد الإلكتروني المذكور أدناه خلال مدة لا تتجاوز April 12,2013\n\nPlease submit your CVs to:\nmshakeel@tenaris.com\n\nلمعلومات حول الشركة:\nwww.tenaris.com\n038127701", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop-tenaris/142533/1", "user": "NaYeF", "ts": 1364822649000, "tid": 142533, "pn": 1}}', 1364822649000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1484975-ise398', 'stk-saleh_alshaheen', 'ISE 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\nمساكم الله بالخير جميعاً\nيسعدني أن اعلن لكم عن فرص تدريب في شركة استشارات بالرياض للراغبين كواب فقط 172-173,173-181.\nالشركة: PM-Partners Saudi Arabia\nالموقع الرياض المروج\nالتخصصات المطلوبة: هندسة صناعية واتوقع مدنية أيضاً, محاسبة ومالية, ادارة وموارد بشرية, مطورين IT.\nملاحظة مهمة جداً: لايوجد أي عمل هندسي بالشركة جميع المهام إدارية بحته.\nعدد المناصب :+6\nخبرة ممتازة وعمل كثير جداً\nالراتب: 2500-6000\nمميزات أخرى: هدف الشركة أختيار الافضل بين الطلاب لوظيفة معهم.\nالراتب على حسب الاداء والتقييم.\nطلاب KFUPM فقط.\nالرجاء ارسال السيرة الذاتية على: szeghough@p3mg\\-mena.com\n\nبالتوفيق للجميع يارب ولاتنسونا من دعواتكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pm-partners/178349/1", "user": "saleh_alshaheen", "ts": 1514135806000, "tid": 178349, "pn": 1}}', 1514135806000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1316571-ise398', 'stk-shubailiferas', 'ISE 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nمن خلال فترة تقديمي على الشركات لاحظت انه بعضها يكرر أسئلة المقابلة الشخصية … من أبرز الشركات اللي سويت معها المقابلة سابك و ارامكو و معادن … زبدة الموضوع عشان ما أطول عليكم … أبحط أسئلة مقابلتي مع كل شركة وبالتوفيق للجميع\nأنا من دفعة 2008 خريج 2013 والجي بي اي فوق 2.5 والتخصص هندسة ميكانيكية تطبيقية\nCOOP at Sabic - Kemya\nSabic – purchasing Department\n\nTalk about yourself?\nIf I meet you someday in the street and we talked then you introduced yourself as a mechanical engineer and I didn’t understand what do you mean by that, can you explain to me what mechanical engineering is?\nIf you have two job offers, the first from Sabic in Jubail and the second from Aramco in Dhahran where you and your family lives, where you will go and why?!\nDid you study ISE 307 (Economics for engineers) at the university? What did you gain from this subject and what the subject talks about in general?\nAre you willing to work in office? Are you willing to work in an environment that does not allow you to go to the field?\nWhat did you do in your COOP training?\n9*7=?\n8*5=?\nDo you want to study master degree? ( I said yes) then he asked how are you going to do so? What do you want to study?\nDo you have any question for us?\nSabic – Kemya\n\nWhen you are planning to get married? (I think the interviewer asked this question to break the ICE)\nTalk about yourself?\nDid you study Thermodynamics in the university? Talk about what do you know in thermodynamic?\nDid you study heat transfer in the university?\nWhat are the differences between thermodynamic and heat transfer?\nDid you take Turbo machinery in the university? (I said No) Then he asked did you work in your COOP with steams turbines? (I said Yes) Then he asked can you explain to me the thermodynamic part and the heat transfer part which are related to the steam turbines?\nCan you draw Rankin cycle? Is it real? Explain it?\nCan you explain Carnot cycle?\nDid you study HVAC in the university? (I said No) then he asked what did you study elective in the university? (Pumping Machinery)\nWhat did you study in pumping?\nHow can you select a pump? What is the equation of specific speed?\nWhat is corrosion? What is NPSHA&NPSHR? Can draw the curves witch related to cavitation on the board? ( I draw Q&H graph with NPSHA&NPSHR once and another time with H&Q& efficiency finally I draw the Liquid, solid and vapor phase diagram)\nWhat is cavitation? Can you define it?\nWhy you want to leave Aramco?\nYou took a course about wielding? Can you define wielding?\nYou’ve done your COOP training in Kemya last year right? What will be your responsibilities as an engineer?\nWhat is root cause? How you can find the root cause of an issue? If you manage to find it what you will do with it?\nWhat do you know about the LDPE plant in Kemya?\nDo you have any question for us?\nAramco\n\nTalk about yourself?\nWhere did you do your COOP training? Talk about the process of Kemya?\nTalk in general about your COOP in Kemya?\nWhat is your senior project? Can you talk about it?\nDo you have any question?\nMa’aden\n\nTalk about yourself out of your C.V?\nWhat do you think about KFUPM? If you go back to high school are you going to joint KFUPM?\nWhy your GPA below 3? Is it because of the faculty of the university? (I said it is because of me)\nIf you have offers from Sabic and Ma’aden, where you will go?\nWhat is the last book that you read?\nWhat are your hopes?\nWhy you will leave your current job?\nDo you have any questions?", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/155059/1", "user": "ShubailiFeras", "ts": 1389092784000, "tid": 155059, "pn": 1}}', 1389092784000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p523176-ise398', 'stk-thamer_al-fakeeh', 'ISE 398', 'info', '{"desc": "Internship &Coop:\nAn internship or co-op at GE gives a student hands-on experience,\nworking on challenging projects with some of the best minds in business. This is a superb opportunity to give his career a head start while making valuable Contacts. The Coop work experience is a vitally important tool for helping a student determines the course of his career, giving him valuable insight into the workplace, useful experience, and helpful contacts for the future.\n\nIf your Major is: Electric Engineering, Mechanical Engineering, Industrial Engineering, or Finance, you may apply through this link:\n\nhttp://www.ge.com/careers/students/internships/middle_east.html\n\nGE invests over $1 billion in training & development. You’ll never stop learning and growing, because GE is a culture committed to education. We’re NOT training Employees; we’re DEVELOPING talent !\n\nRegards,\nThamer Al-Fakeeh\nHR Manager\nGE Energy & Water\nMiddle East & Africa", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/internship-opportunities-with-ge/82198/1", "user": "Thamer_Al-Fakeeh", "ts": 1263459213000, "tid": 82198, "pn": 1}}', 1263459213000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1221037-ise398', 'stk-7uppp', 'ISE 398', 'info', '{"desc": "السلام عليكم\n\nشباب انا بكتب هالموضوع لاني و الله تعبت و زهقت من الهم الي فوق راسي!!\n\nانا المفروض اي اطلع كوأب الصيف هذا و رحت قدمت على كل مكان يوم المهنة قدمت على كل الشركات الي تبغى كوأب و الى اليوم ما في احد رد علي تخصصي هندسة صناعية (ISE) عندي خبرات قديمة و اشياء سويتها ممتازة من ناحية المهارات الخارجية و ال سي في حقي جدا ممتاز ثعدت عليه مدة طويلة و استشرت كثير ناس و عدلت عليه الين لما صار جدا ممتاز!!\n\nقدمت على موقع التدريب و ما ردوا كمان!\n\nو انا الحين خايف يبدا الصيف و لسا ما لقيت كوأب و الي خايف منه اكثر انه بالي يقعد مشغول و اجيب العيد بالاختبارات 😞 😞 😞\n\nيا شباب ابغى نصايحكم ايش اسوي 😞 😐 😐", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/144328/1", "user": "7uppp", "ts": 1368257706000, "tid": 144328, "pn": 1}}', 1368257706000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p244385-ise398', 'stk-user1823', 'ISE 398', 'info', '{"desc": "بكل بساطة…لأن هذي المواد هي روح التخصص و قلبه…و تعطيك الحد الأدنى من حس الهندسة الصناعية\n\nلعلمك أنا طلعت الكوأب و مخلصها كلها و مخلص معاها 422 و 405…حسيت اني لو ما أخذت أي وحدة من هذي المواد ما كنت قدرت أشتغل في البروجكت اللي كنت فيه 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/58043/12", "user": "user1823", "ts": 1203170969000, "tid": 58043, "pn": 12}}', 1203170969000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1466094-ise398', 'stk-mauud777', 'ISE 398', 'info', '{"desc": "تدريب تعاوني للطلاب في الرياض\n\nللتخصصات :\n\nإدارة أعمال , محاسبة , تسويق , هندسة صناعية , موارد الإمداد ( Supply Chain Management)\n\nFahad AlKastaban on Twitter", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/162-163-171/174980/59", "user": "mauud777", "ts": 1484137703000, "tid": 174980, "pn": 59}}', 1484137703000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1472068-ise398', 'stk-hasooona30', 'ISE 398', 'info', '{"desc": "تعلن شركة التنمية غدن للتجارة ومقرها جدة عن توفر فرص تدريبية في برنامج التدريب التعاوني وبالتنسيق مع إدارة التدريب في عمادة شؤون الطلاب :\n\n· الهندسة الصناعية والنظم\n\n· الإدارة\n\n· التسويق\n\no مميزات التدريب: راتب شهري 3500 ريال\n\nعلى الراغبين في التقدم على هذه الفرص التدريبية، إرسال السيرة الذاتية من خلال البريد الالكتروني:\n\narwa@ghadan.com.sa", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/162-163-171/174980/138", "user": "hasooona30", "ts": 1493209119000, "tid": 174980, "pn": 138}}', 1493209119000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1473126-ise398', 'stk-eng_mohammed_al-sham', 'ISE 398', 'info', '{"desc": "Dear All,\n\nI am looking for Summer & Coop Engineers for the following majors:\n\nMechanical Engineering\nIndustrial Engineering\nElectrical Engineering\nIf you are interested, send you CV to: sjobs@qaryansteel.com.\n\nNote: please make sure you type COOP or SUMMER -“Major”-“Name” as subject of your email.\n\nWe are looking for candidates who really want to work & learn, no free rides!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/162-163-171/174980/145", "user": "Eng_Mohammed_Al-sham", "ts": 1494766090000, "tid": 174980, "pn": 145}}', 1494766090000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1362916-ise398', 'stk-eng_why_not', 'ISE 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\nالحمد لله رب العالمين, والصلاة والسلام على سيدنا محمد الصادق الوعد الأمين, اللهم لا علم لنا إلا ما علمتنا إنك أنت العليم الحكيم, اللهم علمنا ما ينفعنا, وانفعنا بما علمتنا, وزدنا علماً, وأرنا الحق حقاً, وارزقنا اتباعه, وأرنا الباطل باطلاً, وارزقنا اجتنابه, واجعلنا ممن يستمعون القول فيتبعون أحسنه, وأدخلنا برحمتك في عبادك الصالحين.\n\nرواد هذا الصرح العظيم أتمنى ان اكون ضيفاً خفيفاًِ عليكم اعين و اعاون و ان شاء الله تنتفعوا بهذا الموضوع البسيط\nسوف اعرض لكم تجاربي من تقديم و مقابلات مع الشركات التي اكرمني الله القبول منها مع العلم اني متخصص في الهندسة الكيميائية و متخرج الترم الماضي\n\nبسم الله على بركه الله\n\nسوف اقسم الموضوع الى 5 اقسام:\n1- كتابه الغرض من العمل مع السي في (الريسمي) خطوه بخطوه\n2- الاستعداد للمقابلات وكيفه التجهيز الايجابي لها\n3- تجاربي الشخصية\n4- الاختيار الأمثل\n5- نصائح محب\n\nالقسم الاول: كتابه الغرض من العمل مع السي في خطوه بخطوه\nلا يخفى عليكم اهميه كتابه السي في ولكن يغيب عن الكثير منا اهميه تحضير و كتابه الغرض من العمل\nIt’s called a Cover Letter or Statement of purpose\nلكي تحضر جيداً لكتابه الغرض من العمل، ينبغي عليك معرفه القسم الذي سوف تعمل فيه المقابلة\nFor example: I am going to have an interview at the project management department\nاسأل نفسك ماذا سوف تعمل في هذا القسم؟ و ماهي المتطلبات و شروطه؟\nخلال هذه الورقة تكتب طموحاتك و تطلعاتك للعمل في هذا الشركة ولماذا تريد انت تعمل في هذا القسم بالتحديد\nهذه امثله لكتابه هذه الخطاب\nhttp://jobsearch.about.com/od/coverlettersamples/a/coverlettsample.htm\nو هنا للسي في\nhttp://jobsearch.about.com/od/sampleresumes/a/sampleresume2.htm\nالجميل في هذه الأمثلة، انها متعددة لتخصصات مختلفة و يوجد بهذا الموقع بعض من النصائح المهمة و التي قد نكون غير ملمين بها\nمن وجهـة نظري المتواضعة قبولك المبدئي في الشركات يتعمد على قوه الغرض من العمل مع السي في\n\nالقسم الثاني: الاستعداد للمقابلات وكيفه التجهيز الايجابي لها\n1- التوكل على الله و الاستخارة\n2- معرفه القسم الذي سوف تقابله\n3- البحث عن عمل هذا القسم والالمام بمخرجاته\n4- معرفه نوع نشاط الشركة على الاقل ابجديات عملها\n5- الثقة بالنفس و عدم التوتر\n6- النوم الجيد قبل المقابلة لكي تكون جاهز 100٪ ان شاء الله\n\nالقسم الثالث: تجاربي الشخصية\nعملت 4 مقابلات من اصل10 ولله الحمد وهم ساتورب و سابك و ارامكو و شلمبرجير . و لقد اعتذرت من بيكر هيوز و وذرفورد و معادن و الصحراء و كريستال وهني ويل\n\nابدء اولا بشركه ساتورب\nالكل يعرف من هي ساتورب مشروع ضخم وجميل من اروع ما شهدت في قطاع النفط و البيتروكيميكال\nمع نهايه شهر فبراير 2014 انتهيت من تعبئه طلب الالتحاق (الابلكيشين) و تم الاتصال بي من قبل موظف الموارد البشرية لعمل مقابله معهم (تمت المقابله خلال اسبوع من تعبئه الابلكيشبن) و الحمد لله ذهبت الى مقر الشركة لعمل المقابلة الشخصية مع قسم الاوبريشين سينسور انجينيرز ( سعودي و جزائري) و للأمانة كانوا في قمه الاخلاق والتواضع. استمرت المقابلة لمده 45 دقيقه على النحو التالي: عرفنا بنفسك؟ ما هو تخصصك؟ من اين حصلت على درجتك العلمية؟ لماذا اخترت تلك الجامعة؟ لماذا تخصصت في الهندسة الكيميائية؟ تكلم عن مشروع التخرج؟ لماذا اخترت هذا المشروع و ما الهدف منه؟ ارسم لنا الفلو شارت تبع الديزان؟ ماهي المنظمات الطلابيه التي اشتركت بها؟ وماذا كان دورك بها؟ هل عملت كوااب خلال دراستك الجامعيه؟ كيف ترى نفسك هنا كا مهندس فرش تنافس المئات من الخريجين لدى ساتورب و كيف ترى نفسك ك مهندس عمليات\n(Process Engineer)؟\nهل تود الحصول على الشهادات العليا؟ ولماذا؟\nوبحكم اني من انني لست من سكان الشرقية تم سؤالي هل تمانع من العمل في الجبيل؟\nو خلال يومين من المقابلة استلمت العرض الرسمي من الشركة\n\nالتجربة الثانية مع سابك\nاتممت التقديم على موقع سابك في منتصف فبراير 2014 والحمد لله اتتني فرصه للمقابلة من شركه صدف التابعة لسابك في الجبيل. بعد مقابلتي بيومين من ساتورب، ذهبت لعمل المقابلة مع صدف التي تعتبر من افضل شركات سابك. المقابلة الشخصية مع قسم الاوبريشين مدير المصنع و سينسور انجينير ( سعوديين) استمرت المقابلة لمده ساعه او اكثر بقليل. و للأمانة تم فصفصت ما تعلمته خلال دراستي الجامعية خلال هذه المقابلة ( بالعامية حللوني صح ) بدء من ماتيريال بالانس الى هيت و ماس ترانسفير و انتهاءَ بمشروع التخرج مع الاخذ بالاعتبار الكيمياء والبوليمرز. المقابلة كانت تخصصيه اكثر من شخصيه.\nالحمد لله استلمت العرض الوظيفي خلال شهر من المقابلة ولله الحمد\n\nالتجربة الثالثة مع أرامكو\nفي بدايه شهر فبراير 2014 استلمت رساله على الايميل من أرامكو (اعلان) اذا كانت لدي الرغبه في العمل لديهم. و بالفعل اتممت من التقديم من خلال موقعهم في نفس اليوم. وخلال اسبوع استلمت ايميل دعوه لحضور ميغا كامبين في فندق ماريوت بالخبر في يوم 17 فبراير حضرت المقابلة معهم. كان هناك حضور كثيف من خريجي الجامعات من داخل و خارج المملكة. بعد التسجيل عند المدخل في خلال نصف ساعه توجهت لعمل المقابلة الشخصية مع قسم OSPAS\nالمقابلة استمرت لمده نصف ساعه و كانت مع اربع مهندسين و في البداية عرفت بنفسي.ما هو تخصصك؟ متى تخرجت؟ من اين حصلت على درجتك العلمية؟ لماذا اخترت تلك الجامعة؟ لماذا تخصصت في الهندسة الكيميائية؟ تكلم عن مشروع التخرج؟ لماذا تريد العمل معنا؟ ماذا تعرف عن قسمنا؟ هل ترغب في اكمال دراستك الجامعية؟ حدثنا عن البرامج التي تحسن استخدامها؟ هل عملت كوااب من قبل؟ وقد اعلموني اني سوف استلم من هم رد قريبا. و بالفعل استلمت الموافقة الرسمية ولله الحمد من القسم خلال نهاية اليوم من احد المهندسين الذي كان موجود في المقابلة.\n\nالتجربة الرابعة شلمبرجير\n\nفي البداية هذه بعض النصائح من موقع الشركة\nhttp://careers.slb.com/experiencedprofessionals/~/media/Files/Careers/leaflets/Interview%20tips.ashx\nللتحضير لمقابله هذه الشركة العملاقة استعنت بمواقع ساعدتني كثيراً للتحضير الأمثل\nhttp://www.glassdoor.com/index.htm\nحيث بالإمكان البحث عن اي شركه عالميه لاستعراض تجارب، مقابلات، رواتب (البعض منها) واشياء مفيده من الممكن ان تخدمك لأخذ إنطباع أولي عن أي شركه عالميه\nوهذا الرابط بالأسفل يعطي بعض من التجارب الجميلة لمتقدمين لشركه شلمبرجير\nhttp://www.glassdoor.com/Interview/Schlumberger-Field-Specialist-Interview-Questions-EI_IE588.0,12_KO13,29.htm\nتجد عن المتقدمين للكواب او فرش او خبير من مختلف دول العالم\nوهنا بعض الأسئله مع الاجوبه المحموده و المذمومه ومدى تأثيرها على المقابله بالإضافه لبعض المواقف و النصائح\nhttp://interview-questions1.co.uk/Schlumberger/interview+questions\nو اخيرا هذا الموقع يشرح ما يمكن توقعه خلال المقابله مع بعض الإرشادات و التعليمات\nhttp://www.petroleum-engineering.net/schlumberger-interview-how-schlumberger-will-interview-you/\n\nاتممت طلب الالتحاق عن طريق موقعهم في نهايه مارس 2014 وجاني اتصال منهم بعد اسبوع استمرت لمده ساعه. كلمتني موظفه الموارد البشرية لمده ساعه تقريباً. في البداية قالت لي تحدث عن نفسك؟ ما لذي دفعك لطلب الالتحاق لـ شلمبرجير ؟ هل عملت كوااب؟ ماذا تعرف عن شلمبرجير ؟ هل لديك مانع في العمل في الفيلد؟ او العمل في مواقع مختلفة؟ هل تمانع في العمل في داخل و خارج المملكة؟ ماهي اللغات التي تتحدثها؟ و أين تعلمتها؟ حدثني عن دراستك؟ هل شاركت في أعمال تطوعيه؟ ماهي نقاط ضعفك؟ قوتك؟ ما رايك في العمل الجماعي و الفردي؟\nوقبل إنهاء المكالمة دعتني لحضور مقابله شخصيه في الشركة في نفس الأسبوع (بعد يومين). و هنا نأتي للمقابلة الثانية\nحضرت لمقر الشركة وقابلت 3 مهندسين من جنسيات مختلفة مع موظفه الموارد البشرية. كان عدد المتقدمين 7 في ذلك اليوم ومن تخصصات مختلفة. الهندسة الكهربائية و الصناعية و الكيميائية و الميكانيكية و الكومبيوتر. هذا أعطاني الانطباع المبدئي عن هذه الشركة لأنها تريد مهندسين من تخصصات مختلفة تدربهم و تصنع منهم ما تريد في خلال الثلاث سنوات الأولى من عملهم. قابلنا المهندس محمد الخضري (إنسان في قمه اللباقة و الاحترام) و قدم لنا لمحه بسيطة عن الشركة لمده ساعه تقريباً. و بعد ذلك بدائنا الامتحان المقدم من الشركة ( انجليزي، رياضيات، ميكانيكا، فيزياء كهربائية، أسئلة عامه) استمر الاختبار لمده ساعتين تقريباً. و عندما تم الانتهاء من الاختبار تم تقسيمنا إلى مجموعتين 3 و 4. تم إعطائنا 20 ورقه و مقص و لصق و مسطره. المطلوب كان أن نبني برج لا يقل طوله عن 20 سم و باستطاعته أن يتحمل أكبر عدد من كور الجولف. المغزى من هذا العمل غير الظاهري هو العمل لإنجاز مشروع بمواصفاته المطلوبه ولكن الغير ظاهر هو مهارات العمل و الإتصال مع الاخرين ( الليدرشيب و التيم ورك) و بعد الإنتهاء من هذا الجزء كل فريق قدم عمله على طريقه (البرزنتيشين) . أخذنا بريك لمده نصف ساعه للغذاء و صلاه الظهر. بعد ذلك مباشره تم البدء لعمل المقابلات الشخصيه. في البداية عملت برزنتيشين عن نفسي ( مقدمه، السينيور ديزاين، الكواب) و بعد ذلك تم سؤالي نفس أسئلة المقابلة الهاتفية في خلال 10 -15 دقائق. لم نتطرق إلى الدراسة او مواد التخصص بشكل دقيق لكن تم التحدث عن طبيعة العمل لديهم. عرضوا علي البدء في العمل لديهم في اوروبا الشرقية او البرازيل ( بحسب احتياجهم) و من ثم عرضوا علي منهجيه العمل ( 4 اسابيع عمل و 3 اسابيع إجازة) في اول سنه وخلال السنتين الأخريين سوف يتم تحديدها لاحقاً. المسمى الوظيفي سوف تكون مهندس ميداني و ارفقوا لي بعض الأمثلة التي تشرح مهمه عملي . و في النهاية قالوا لي ننتظر منك الرد في خلال أسبوع سواءً بالموافقة او بالرفض. المقابلة استمرت أكثر من نصف ساعه و الحمد لله على كل حال\nبلغت بالموافقه المبدئيه للعمل في الشركه بعد 4 أيام من المقابله وطلب مني الحضور لبدء الفيلد اكسبوشر لمده أسبوعين مع الكشف الطبي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-z/160911/1", "user": "ENG_WHY_NOT", "ts": 1399596425000, "tid": 160911, "pn": 1}}', 1399596425000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p426355-ise398', 'stk-ise-ise', 'ISE 398', 'info', '{"desc": "اخوي من تجربة لا تعتمد على ادارة التدريب والله ما عندهم سالفة\n\nلاسف هناك مشكلة اما ان الشركات غير متواصلة مع الجامعة او الجامعة غير قادرة على التواصل مع الشركات\n\nان تخصص صناعية بس كان موجود في الموقع ايام التسجيل ثمان فرص و عدد الطلاب 32\n\nفما جاني رد من الجامعة\n\nفبعد الاختبارات رحت لشركات وقالوا لي ليه ما قدمت منزمان مع العلم الشركات اللي رحت لهم ما كانوا موجدين في موقع ادارة التدريب وكانوا محتجين للهندسة الصناعية\n\nالمهم لحق عمرك و اتصل على مدير التدريب ماجد الحارثي 038604433\n\nواذا كنت في الرياض في شركة التقنيات المتقدمة و الصافي , بنك الراجحي و معادن و الاتصالات\n\nطالبين طلاب coop\n\nوبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/75017/8", "user": "ISE-ISE", "ts": 1246794799000, "tid": 75017, "pn": 8}}', 1246794799000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p940348-ise398', 'stk-sub_ze_0_ro', 'ISE 398', 'info', '{"desc": "بسم الله الرحمن الرحيم…\n\nكيفكم شباب…\n\nلاهنتم ودي اعرف هل التحويل من سمر ترينيتق الى كوأب يحتاج مجهود…\n\nأنا اول حولت الى هندسه صناعيه بس سجلوني سمر ترينينق بالرغم من اني مسجل\nفي ورقة تحويل التخصص… ISE Applied\n\nكيف الحل الحين… هل اروح للهندي اللي بمبنى 9 والا اروح للدكتور السني… واشرح له الوضع…\n\nترمين بالتخصص وتوي اكتشف اني سمر ترينينق…\n\nمشكورين شباب مقدما…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/115933/1", "user": "sub_ze_0_ro", "ts": 1322687482000, "tid": 115933, "pn": 1}}', 1322687482000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1468750-ise398', 'stk-n.a.s.s.e.r', 'ISE 398', 'info', '{"desc": "مساء النور هلا بك\n\nكانت المقابلة مع قسم الانسترومنت مع واحد ماليزي وكان اغلب الموجودين للمقابلة من نفس التخصص غالبا انا الوحيد يمكن اللي كنت اندستريال\n\nكانت الأسئلة عامة جدا\nكالعادة تكلم عن نفسك\nوش مشروع تخرجك؟\nعن الكواب والبروجكتات اللي سويتها ؟\nماذا تعرف عن ساسرف؟\nلماذا قدمت لساسرف ؟\n\nوقالوا لي بنرد لك بعد اسبوعين بالكثير\n\nبالنسبة للعدد كان آخر واحد رقمة على ما أظن 24", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/176049/9", "user": "n.a.s.s.e.r", "ts": 1487625580000, "tid": 176049, "pn": 9}}', 1487625580000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p519890-ise398', 'stk-ofesofes', 'ISE 398', 'info', '{"desc": "السلام عليكم\n\nيا جماعة موظف في شركة التركي للخرسانه اللي في الخبر\nنريد واحد او اثنين من طلاب الهندسة الكيميائية والهندسة الصناعية\nللتطبيق واخذ co-opفي هذي الشركة\nاللي عنده استعداد يراسلني على ايميلي وعلى فكرة اللي عنده استعداد موظوعة ان شاء الله منتهي وجاهز\nkfupmwarriour2009@hotmail.com\nفي اسرع وقت تراهم مستعجلين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/co-op/81999/1", "user": "ofesofes", "ts": 1263043607000, "tid": 81999, "pn": 1}}', 1263043607000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p849357-ise398', 'stk-jare7', 'ISE 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nبعد اذن صاحب الموضوع… مااعرف وين المفروض اكتب هالموضوع\nيوجد فرص تدريب (COOP)في شركة السلفونات العربية في جدة .\nموظف الموارد البشرية في الشركة طلب مني اخبر الطلاب عن هذه الفرص\nالفرص المتوفرة حاليا للتدريب التعاوني في الشركة :\nهندسة كيميائية(1)\nهندسة صناعية (1)\nمالية (2)\nنظم (1)\nمحاسبة (2)\nادارة (2)\nتسويق (1)\n\nالي يبغى يتدرب عند الشركة او يعرف احد ما حصل شركة للتدريب التعاوني الى الان\nهالفرص موجودة . وللتواصل مع الموظف في الموارد البشرية (حمزة محمد داوود):\nالجوال : 0500110261\nالمكتب:026082258 تحويلة 231\nالايميل : hamza@mqasons.com\n\nوللاستفسار ارجو التواصل المباشر مع الموظف لاني مشغول مع الاختبارات وماادخل المنتدى .\nواذا كان الموضوع مو في مكانه … ارجو من احدكم ان يتفضل ويكتب موضوع جديد في القسم المخصص .\n\nواكرر اعتذاري من صاحب الموضوع … انا كتبت هنا لان اغلب الي عندهم تدريب يدخلون هالموضوع .\nوبالتوفيق للجميع … واعاننا الله واياكم …\nلا تنسوني من دعآئكم .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/107838/41", "user": "jare7", "ts": 1307643469000, "tid": 107838, "pn": 41}}', 1307643469000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1482725-ise398', 'stk-user10218', 'ISE 398', 'info', '{"desc": "coop\nMenaBev\nجده\n4500 ريال\n,CISE,AEE,ISE,AME,ACHEM\nAmani.Jamalaldeen@menabev.com\n…\nDear KFUPM Internship Applicant,\n\nMenaBev is a flagship franchise bottler for PepsiCo International in the MEA (Middle – East and Africa) region, with over 50 years of rich history. we are on the last step of start operating PepsiCo largest Pepsi Bottling plant in the world, utilizing the state-of the-art Manufacturing and Warehousing technology. The Company effectively services its large customer base across the Western Region with a strong Sales Organization and its well-placed 17 Distribution Centres. It has developed into a highly professional organization, with a workforce of over 1,200 employees, based on robust systems and processes, providing a fair and high-performance work environment which is conducive to employee development, engagement and personal growth.\nYour CV has been shared by the KFUPM students training department, Hence, kindly provide us with below requirements:\n\nCurriculum Vitae (Updated CV Softcopy)\nEducation (Transcript Softcopy)\nMenaBev Internship form.\nWe will be available in the KFUPM COOP event this week for further information you may require.\nKindly select your most (1) to least (6) preferable career areas as per the below example:\n\nThanks & Best Regards,\nTalent Team", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/172-173-181/177905/11", "user": "user10218", "ts": 1509459735000, "tid": 177905, "pn": 11}}', 1509459735000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
